        super(VaultCLI, self).init_parser(usage='usage: %%prog [%s] [options] [vaultfile.yml]' % '|'.join(sorted(self.VALID_ACTIONS)), desc='encryption/decryption utility for Ansible data files', epilog="\nSee '%s <command> --help' for more information on a specific command.\n\n" % os.path.basename(sys.argv[0]))
        opt_help.add_vault_options(self.parser)
        opt_help.add_vault_rekey_options(self.parser)
        self.set_action()

    def post_process_args(self, options, args):
        options, args = super(VaultCLI, self).post_process_args(options, args)
        self.validate_conflicts(options, vault_opts=True, vault_rekey_opts=True)
        display.verbosity = options.verbosity
        if options.vault_ids:
            for vault_id in options.vault_ids:
                if u';' in vault_id:
                    raise AnsibleOptionsError("'%s' is not a valid vault id. The character ';' is not allowed in vault ids" % vault_id)
        if self.action not in self.can_output:
            if not args:
                raise AnsibleOptionsError('Vault requires at least one filename as a parameter')
        elif options.output_file and len(args) > 1:
            raise AnsibleOptionsError('At most one input file may be used with the --output option')
        if self.action == 'encrypt_string':
            if '-' in args or not args or options.encrypt_string_stdin_name:
                self.encrypt_string_read_stdin = True
            if options.encrypt_string_prompt and self.encrypt_string_read_stdin:
                raise AnsibleOptionsError('The --prompt option is not supported if also reading input from stdin')
        return (options, args)

    def run(self):
        super(VaultCLI, self).run()
        loader = DataLoader()
        old_umask = os.umask(63)
        vault_ids = list(context.CLIARGS['vault_ids'])
        default_vault_ids = C.DEFAULT_VAULT_IDENTITY_LIST
        vault_ids = default_vault_ids + vault_ids
        if self.action in ['decrypt', 'view', 'rekey', 'edit']:
            vault_secrets = self.setup_vault_secrets(loader, vault_ids=vault_ids, vault_password_files=list(context.CLIARGS['vault_password_files']), ask_vault_pass=context.CLIARGS['ask_vault_pass'])
            if not vault_secrets:
                raise AnsibleOptionsError("A vault password is required to use Ansible's Vault")
        if self.action in ['encrypt', 'encrypt_string', 'create']:
            encrypt_vault_id = None
            if self.action not in ['edit']:
                encrypt_vault_id = context.CLIARGS['encrypt_vault_id'] or C.DEFAULT_VAULT_ENCRYPT_IDENTITY
            vault_secrets = None
            vault_secrets = self.setup_vault_secrets(loader, vault_ids=vault_ids, vault_password_files=context.CLIARGS['vault_password_files'], ask_vault_pass=context.CLIARGS['ask_vault_pass'], create_new_password=True)
            if len(vault_secrets) > 1 and (not encrypt_vault_id):
                raise AnsibleOptionsError('The vault-ids %s are available to encrypt. Specify the vault-id to encrypt with --encrypt-vault-id' % ','.join([x[0] for x in vault_secrets]))
            if not vault_secrets:
                raise AnsibleOptionsError("A vault password is required to use Ansible's Vault")
            encrypt_secret = match_encrypt_secret(vault_secrets, encrypt_vault_id=encrypt_vault_id)
            self.encrypt_vault_id = encrypt_secret[0]
            self.encrypt_secret = encrypt_secret[1]
        if self.action in ['rekey']:
            encrypt_vault_id = context.CLIARGS['encrypt_vault_id'] or C.DEFAULT_VAULT_ENCRYPT_IDENTITY
            new_vault_ids = []
            if encrypt_vault_id:
                new_vault_ids = default_vault_ids
            if context.CLIARGS['new_vault_id']:
                new_vault_ids.append(context.CLIARGS['new_vault_id'])
            new_vault_password_files = []
            if context.CLIARGS['new_vault_password_file']:
                new_vault_password_files.append(context.CLIARGS['new_vault_password_file'])
            new_vault_secrets = self.setup_vault_secrets(loader, vault_ids=new_vault_ids, vault_password_files=new_vault_password_files, ask_vault_pass=context.CLIARGS['ask_vault_pass'], create_new_password=True)
            if not new_vault_secrets:
                raise AnsibleOptionsError("A new vault password is required to use Ansible's Vault rekey")
            new_encrypt_secret = match_encrypt_secret(new_vault_secrets, encrypt_vault_id=encrypt_vault_id)
            self.new_encrypt_vault_id = new_encrypt_secret[0]
            self.new_encrypt_secret = new_encrypt_secret[1]
        loader.set_vault_secrets(vault_secrets)
        vault = VaultLib(vault_secrets)
        self.editor = VaultEditor(vault)
        self.execute()
