class ConsulConfig(dict):

    def __init__(self):
        self.read_settings()
        self.read_cli_args()

    def has_config(self, name):
        if hasattr(self, name):
            return getattr(self, name)
        else:
            return False

    def read_settings(self):
        """ Reads the settings from the consul.ini file """
        config = ConfigParser.SafeConfigParser()
        config.read(os.path.dirname(os.path.realpath(__file__)) + '/consul.ini')
        config_options = ['host', 'token', 'datacenter', 'servers_suffix', 'tags', 'kv_metadata', 'kv_groups', 'availability', 'unavailable_suffix', 'available_suffix', 'url', 'domain']
        for option in config_options:
            value = None
            if config.has_option('consul', option):
                value = config.get('consul', option)
            setattr(self, option, value)

    def read_cli_args(self):
        """ Command line argument processing """
        parser = argparse.ArgumentParser(description='Produce an Ansible Inventory file based nodes in a Consul cluster')
        parser.add_argument('--list', action='store_true', help='Get all inventory variables from all nodes in the consul cluster')
        parser.add_argument('--host', action='store', help='Get all inventory variables about a specific consul node,               requires datacenter set in consul.ini.')
        parser.add_argument('--datacenter', action='store', help='Get all inventory about a specific consul datacenter')
        args = parser.parse_args()
        arg_names = ['host', 'datacenter']
        for arg in arg_names:
            if getattr(args, arg):
                setattr(self, arg, getattr(args, arg))

    def get_availability_suffix(self, suffix, default):
        if self.has_config(suffix):
            return self.has_config(suffix)
        return default

    def get_consul_api(self):
        """get an instance of the api based on the supplied configuration"""
        host = 'localhost'
        port = 8500
        token = None
