          o = urlparse(self.url)
          if o.hostname:
              host = o.hostname
          if o.port:
              port = o.port
          if o.scheme:
              scheme = o.scheme

      if hasattr(self, 'token'):
          token = self.token
          if not token:
              token = 'anonymous'
      return consul.Consul(host=host, port=port, token=token, scheme=scheme)

